import{_ as i,C as r,o as s,c as o,j as e,a as h,E as l,a5 as n}from"./chunks/framework.D_J2JZBr.js";const P=JSON.parse('{"title":"SI100B 信息科学技术导论","description":"聚焦 SI100B 的 EE 部分，理解从数字逻辑、Logisim 到 miniCPU 的学习路径。","frontmatter":{"title":"SI100B 信息科学技术导论","description":"聚焦 SI100B 的 EE 部分，理解从数字逻辑、Logisim 到 miniCPU 的学习路径。"},"headers":[],"relativePath":"shanghaitech/courses/si100b.md","filePath":"shanghaitech/courses/si100b.md","lastUpdated":1795531638000}'),c={name:"shanghaitech/courses/si100b.md"};function d(u,t,g,b,p,m){const a=r("CourseTable");return s(),o("div",null,[t[0]||(t[0]=e("h1",{id:"si100b-信息科学技术导论",tabindex:"-1"},[h("SI100B 信息科学技术导论 "),e("a",{class:"header-anchor",href:"#si100b-信息科学技术导论","aria-label":'Permalink to "SI100B 信息科学技术导论"'},"​")],-1)),l(a,{codes:"SI100B"}),t[1]||(t[1]=n('<div class="info custom-block"><p class="custom-block-title">版本边界</p><p>本页重点介绍娄鑫老师公开课程页中的 <strong>EE Part</strong>，不是整门 SI100B 所有模块的完整大纲。课程表采用 2026–2027 学年教师名单；多模块、不同班级与往届版本教师可能不同。</p></div><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p>SI100B 是信息科学的入门窗口。在 2026 级 EE 培养方案中，它属于自然科学通识的信息课程群，建议大一秋修读。EE 部分让你第一次把“计算”理解成可搭建的硬件，而不只是屏幕上的程序。</p><p>官方开课表未列先修要求。开始前会基本进制转换、能按步骤检查逻辑条件即可，不必提前学完整本芯片教材。之后可接<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115b">数字电路 EE115B</a>，也能为<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cs110">计算机体系结构 CS110</a>中的数据通路建立直觉。更长的路线见<a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/">数字学习地图</a>。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><p>公开课程页的 <strong>2026 秋 EE Lectures</strong> 按以下顺序展开：</p><table tabindex="0"><thead><tr><th>讲次</th><th>核心内容</th><th>学习检查点</th></tr></thead><tbody><tr><td>1</td><td>导论</td><td>说明数字系统怎样表示和处理信息</td></tr><tr><td>2</td><td>逻辑门与组合逻辑</td><td>从真值表得到组合功能，区分输入与输出</td></tr><tr><td>3</td><td>数制</td><td>对齐位宽、有符号数和编码的含义</td></tr><tr><td>4</td><td>算术电路</td><td>将加法等运算分解为可连接的模块</td></tr><tr><td>5</td><td>存储与时序逻辑</td><td>理解电路如何保存状态，以及时钟的作用</td></tr><tr><td>6</td><td>计算机系统</td><td>把运算、存储和控制连接为系统</td></tr></tbody></table><p>不要把“画出来能亮灯”当作理解完成。应能解释一个输出来自哪条逻辑路径、寄存器何时更新，以及输入改变后哪些节点不应立刻改变。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><p>公开页提供 Logisim-evolution 教程与课程版安装包。<strong>2026 春版本</strong>还公开了从基础作业、算术逻辑单元（Arithmetic Logic Unit，ALU）到 miniCPU 的资料。miniCPU 分为 Python 汇编器与 Logisim 电路两个子任务，配套材料涉及 RISC-V 背景、汇编、指令编码和微结构。</p><p>建议按“单模块 → 模块连接 → 指令行为”验证：先穷举小规模组合逻辑，再检查寄存器复位与更新，最后用短程序跟踪程序计数器、操作数和结果。保留能复现错误的最短输入，不要仅截取最终成功画面。具体题目与交付物以所选学期 Project Document 为准；春季项目不代表秋季必然使用同一任务。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li><a href="https://vsplab.cn/courses/si100b/" target="_blank" rel="noreferrer">VSPLab SI100B 课程页</a>：按学期选择课件、教程、作业与项目资料。</li><li>课程指定版本的 Logisim-evolution：从课程页获取，优先保证与模板、自测和评测环境一致。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字基础自学</a>：需要额外练习布尔逻辑与时序概念时使用；不必同时启动多套教程。</li></ul><p>课程页已提供足够明确的学习入口。自学资料可以帮助理解，但不能替代本学期的端口命名、文件格式和提交要求。</p><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 春 / 秋版本。</strong> 春季公开资料包含 miniCPU，秋季页面提供 EE 讲义与 HW0；页面注明秋季 HW0 不计入课程成绩。这只是某项作业的规则，不能推导出整门课程的评分比例；完整总评构成请查当学期大纲。</p><ul><li><strong>难点</strong>：把程序的顺序执行与电路的并行传播区分开，尤其是位宽、进位、寄存器更新和控制信号。</li><li><strong>准备</strong>：先熟悉二进制、逻辑门、真值表；遇到汇编器任务再补 Python 字符串解析与数值处理。</li><li><strong>工具链</strong>：安装后先打开课程模板并完成一次小电路自测，确认文件能保存、重开、运行，再开始大型项目。</li><li><strong>协作边界</strong>：讨论电路原理与调试方法，不交换整份可提交电路；测试应由自己理解和解释。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/digital-vlsi">数字 VLSI</a>：逻辑模块最终如何成为芯片。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/architecture">计算机体系结构</a>：指令与数据通路如何连接。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/vsplab">上科大 VSPLab</a>：了解公开课程资源与研究入口。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过这门课，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充不同模块、班级与学期的学习经验。请注明版本，不公开课程答案或个人信息。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://vsplab.cn/courses/si100b/" target="_blank" rel="noreferrer">VSPLab SI100B 官方课程资源</a>：2026 秋讲义、HW0 与 2026 春 miniCPU 资料。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：课程表信息。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Undergraduate/Degree%20Programmes/2026%20Bachelor%20Degree%20Prorgams%20in%20EE.htm" target="_blank" rel="noreferrer">2026 级 EE 培养方案</a>：课程归类与建议学期。</li></ul>',22))])}const _=i(c,[["render",d]]);export{P as __pageData,_ as default};
